import json
import csv
import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq
from datetime import datetime

FIELD_MAP = {
    "id": "user_id",
    "userId": "user_id",
    "user_id": "user_id",
    "full_name": "name",
    "userName": "name",
    "name": "name",
    "email": "email",
    "email_address": "email",
    "registration_date": "created_date",
    "created_at": "created_date",
    "joined": "created_date",
    "status": "status",
    "is_active": "status",
    "active": "status",
}

OUTPUT_FIELDS = ["user_id", "name", "email", "created_date", "status"]


def normalize_date(val):
    if val is None:
        return None
    s = str(val).strip()
    for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%m/%d/%Y", "%d-%m-%Y"):
        try:
            return datetime.strptime(s, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue
    return s


def normalize_status(val):
    if val is None:
        return None
    if isinstance(val, bool):
        return "active" if val else "inactive"
    s = str(val).strip().lower()
    if s in ("true", "1", "yes", "active"):
        return "active"
    if s in ("false", "0", "no", "inactive"):
        return "inactive"
    return s


def remap(record: dict, source: str) -> dict:
    out = {}
    for k, v in record.items():
        unified = FIELD_MAP.get(k)
        if unified is None:
            continue
        if unified == "user_id":
            v = int(v)
        elif unified == "created_date":
            v = normalize_date(v)
        elif unified == "status":
            v = normalize_status(v)
        elif v is not None:
            v = str(v).strip() if not isinstance(v, str) else v.strip()
        out[unified] = v
    return out


def load_source_a(path):
    with open(path) as f:
        data = json.load(f)
    return [remap(r, "source_a") for r in data]


def load_source_b(path):
    rows = []
    with open(path, newline="") as f:
        for row in csv.DictReader(f):
            rows.append(remap(row, "source_b"))
    return rows


def load_source_c(path):
    df = pd.read_parquet(path)
    return [remap(r, "source_c") for r in df.to_dict(orient="records")]


def merge(sources: list[tuple[str, list[dict]]]):
    """
    sources: ordered list of (source_name, records) from highest to lowest priority.
    Returns (merged_dict keyed by user_id, conflicts list).
    """
    # Collect all values per user per field per source
    per_user: dict[int, dict[str, dict[str, any]]] = {}

    for source_name, records in sources:
        for rec in records:
            uid = rec["user_id"]
            if uid not in per_user:
                per_user[uid] = {f: {} for f in OUTPUT_FIELDS}
            for field in OUTPUT_FIELDS:
                val = rec.get(field)
                if val is not None:
                    per_user[uid][field][source_name] = val

    merged = {}
    conflicts = []
    priority_order = [name for name, _ in sources]

    for uid, fields in per_user.items():
        row = {"user_id": uid}
        for field in OUTPUT_FIELDS:
            if field == "user_id":
                continue
            vals = fields[field]
            if not vals:
                row[field] = None
                continue

            unique_vals = set(vals.values())
            # Pick value from highest-priority source that has it
            selected = None
            for src in priority_order:
                if src in vals:
                    selected = vals[src]
                    break

            if len(unique_vals) > 1:
                conflict = {
                    "user_id": uid,
                    "field": field,
                    "values": vals,
                    "selected": selected,
                }
                conflicts.append(conflict)

            row[field] = selected

        merged[uid] = row

    return merged, conflicts


def main():
    sources = [
        ("source_a", load_source_a("/data/source_a/users.json")),
        ("source_b", load_source_b("/data/source_b/users.csv")),
        ("source_c", load_source_c("/data/source_c/users.parquet")),
    ]

    merged, conflicts = merge(sources)

    # Build DataFrame in user_id order
    rows = sorted(merged.values(), key=lambda r: r["user_id"])
    df = pd.DataFrame(rows, columns=OUTPUT_FIELDS)
    df["user_id"] = df["user_id"].astype("int64")

    # Write parquet
    table = pa.Table.from_pandas(df, preserve_index=False)
    pq.write_table(table, "/app/merged_users.parquet")
    print(f"Written /app/merged_users.parquet ({len(df)} rows)")

    # Write conflict report
    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w") as f:
        json.dump(report, f, indent=2)
    print(f"Written /app/conflicts.json ({len(conflicts)} conflicts)")

    # Print summary
    print("\nMerged users:")
    print(df.to_string(index=False))
    print("\nConflicts:")
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()

